import React, { lazy, Suspense } from 'react'
import ReactDOM from 'react-dom/client'
import { Auth0Provider } from '@auth0/auth0-react'
import { I18nextProvider } from 'react-i18next'
import i18n from './i18n/index.js'
import './index.css'

// PWA service worker (generated by vite-plugin-pwa): app shell + models +
// fonts precached, API reads NetworkFirst, chat posts replay on reconnect.
if ('serviceWorker' in navigator && import.meta.env.PROD) {
  import('virtual:pwa-register').then(({ registerSW }) => {
    registerSW({ immediate: true })
  }).catch(() => {})
}

// The marketing website and the XR platform are two separate applications that
// share this entry point, and only one ever runs — `MODE` decides which at build
// time. Both used to be imported statically, so whichever one was *not* selected
// was still bundled, parsed and paid for on every load. Importing the chosen one
// dynamically keeps the other out of the initial graph entirely; because `MODE`
// is a build-time constant, Rollup also drops the unused branch at build time.
const isPlatform = import.meta.env.MODE === 'platform'

const App = lazy(() =>
  isPlatform
    ? import('./AppPlatform.jsx').then((m) => ({ default: m.default }))
    : import('./App.jsx').then((m) => ({ default: m.default }))
)

/** Shown for the moment the selected application chunk is in flight. */
const BootFallback = () => (
  <div
    style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: '#020617',
    }}
    aria-busy="true"
    aria-live="polite"
  >
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1rem' }}>
      <img src="/kev-logo.svg" alt="" width="56" height="56" />
      <span
        style={{
          fontFamily: 'IBM Plex Mono, monospace',
          fontSize: '0.65rem',
          letterSpacing: '0.2em',
          textTransform: 'uppercase',
          color: 'rgba(103, 232, 249, 0.7)',
        }}
      >
        Loading KEV
      </span>
    </div>
  </div>
)

// PostHog is write-only product analytics: nothing on screen depends on it. It
// was imported statically, which put ~240 kB — a third of the entry chunk — on
// the critical path ahead of first paint. Fetched dynamically instead, so the
// app renders while it arrives. The key is still resolved at build time, so an
// unconfigured deployment does not request the SDK at all.
if (import.meta.env.VITE_POSTHOG_KEY) {
  const posthogKey = import.meta.env.VITE_POSTHOG_KEY
  const posthogHost = import.meta.env.VITE_POSTHOG_HOST ?? 'https://us.i.posthog.com'
  import('posthog-js')
    .then(({ default: posthog }) => {
      posthog.init(posthogKey, { api_host: posthogHost, capture_pageview: true })
    })
    .catch(() => {
      // Analytics failing must never take the school down with it.
    })
}

const auth0Domain = import.meta.env.VITE_AUTH0_DOMAIN
const auth0ClientId = import.meta.env.VITE_AUTH0_CLIENT_ID

const app = (
  <Suspense fallback={<BootFallback />}>
    <App />
  </Suspense>
)

const root = (
  <React.StrictMode>
    <I18nextProvider i18n={i18n}>
      {auth0Domain && auth0ClientId ? (
        <Auth0Provider
          domain={auth0Domain}
          clientId={auth0ClientId}
          authorizationParams={{
            redirect_uri: window.location.origin,
            audience: 'https://api.kev.sansmercantile.com',
          }}
        >
          {app}
        </Auth0Provider>
      ) : (
        app
      )}
    </I18nextProvider>
  </React.StrictMode>
)

ReactDOM.createRoot(document.getElementById('root')).render(root)
